package com.slayerloadout;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Getter;

/**
 * Detects the player's current slayer task by parsing game chat messages.
 *
 * <p>Chat parsing is used (rather than reading internal varbits) because the
 * message formats are stable across game updates and exactly match the user
 * action of "checking" a task at a slayer master, on an enchanted gem, or via
 * the built-in {@code !task} command. Both new-assignment and "currently
 * assigned" (check) phrasings are handled, including Konar's location suffix.</p>
 */
public class SlayerTaskTracker
{
	// Matches e.g.
	//   "You are assigned to kill abyssal demons; only 134 more to go."
	//   "You're assigned to kill 132 aberrant spectres; only 132 more to go."
	//   "You're currently assigned to kill gargoyles; only 122 more to go."
	//   "You are assigned to kill abyssal demons in the Catacombs of Kourend; only 145 more to go."
	private static final Pattern ASSIGNMENT = Pattern.compile(
		"(?:you are assigned to kill|you're assigned to kill|you are now assigned to kill|"
			+ "you have been assigned to kill|you're currently assigned to kill) "
			+ "(?:\\d[\\d,]* )?"
			+ "(?<name>.+?)"
			+ "(?: (?:in|on|at|near|throughout|around|under|inside|within) .+?)?"
			+ "[;,] only (?<amount>[\\d,]+) more to go.*",
		Pattern.CASE_INSENSITIVE);

	private static final Pattern COMPLETED = Pattern.compile(
		"you (?:have completed your task|need a new task)", Pattern.CASE_INSENSITIVE);

	@Getter
	private String currentTask;

	/**
	 * Feed a chat message to the tracker.
	 *
	 * @return {@code true} if this message changed the detected task
	 */
	public boolean parse(String rawMessage)
	{
		if (rawMessage == null)
		{
			return false;
		}

		final String message = stripTags(rawMessage).trim();

		final Matcher m = ASSIGNMENT.matcher(message);
		if (m.matches())
		{
			final String name = m.group("name").trim();
			if (!name.isEmpty() && !name.equalsIgnoreCase(currentTask))
			{
				currentTask = name;
				return true;
			}
			return false;
		}

		if (COMPLETED.matcher(message).find())
		{
			if (currentTask != null)
			{
				currentTask = null;
				return true;
			}
		}

		return false;
	}

	public void setCurrentTask(String task)
	{
		this.currentTask = (task == null || task.trim().isEmpty()) ? null : task.trim();
	}

	/** Remove RuneLite/Jagex colour and image tags from a chat message. */
	private static String stripTags(String s)
	{
		return s.replaceAll("<[^>]*>", "");
	}
}

package com.slayerloadout;

/**
 * Equipment slots used by the loadout. The declaration order is the order the
 * slots are rendered in the side panel.
 */
public enum GearSlot
{
	HEAD("Head"),
	CAPE("Cape"),
	NECK("Neck"),
	WEAPON("Weapon"),
	BODY("Body"),
	SHIELD("Shield"),
	LEGS("Legs"),
	HANDS("Hands"),
	FEET("Feet"),
	RING("Ring"),
	AMMO("Ammo");

	private final String displayName;

	GearSlot(String displayName)
	{
		this.displayName = displayName;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	/**
	 * Parse a slot name from the JSON data file. Returns null for unknown slots
	 * so the data file can evolve without crashing older clients.
	 */
	static GearSlot fromKey(String key)
	{
		if (key == null)
		{
			return null;
		}
		try
		{
			return GearSlot.valueOf(key.trim().toUpperCase(java.util.Locale.ENGLISH));
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	/**
	 * Map a RuneLite equipment slot index (matching EquipmentInventorySlot's
	 * slot idx) to a {@link GearSlot}. Returns null for slots we don't display
	 * (arms, hair, jaw).
	 */
	static GearSlot fromEquipmentSlot(int idx)
	{
		switch (idx)
		{
			case 0: return HEAD;
			case 1: return CAPE;
			case 2: return NECK;
			case 3: return WEAPON;
			case 4: return BODY;
			case 5: return SHIELD;
			case 7: return LEGS;
			case 9: return HANDS;
			case 10: return FEET;
			case 12: return RING;
			case 13: return AMMO;
			default: return null;
		}
	}
}

package com.slayerloadout;

/**
 * A snapshot of the player's (boosted) combat levels, read from the client and
 * used by {@link DpsCalculator}.
 */
public class PlayerStats
{
	public final int attack;
	public final int strength;
	public final int defence;
	public final int ranged;
	public final int magic;
	public final int hitpoints;

	public PlayerStats(int attack, int strength, int defence, int ranged, int magic, int hitpoints)
	{
		this.attack = attack;
		this.strength = strength;
		this.defence = defence;
		this.ranged = ranged;
		this.magic = magic;
		this.hitpoints = hitpoints;
	}

	/** A sensible default (maxed) used before the client has reported real levels. */
	public static PlayerStats maxed()
	{
		return new PlayerStats(99, 99, 99, 99, 99, 99);
	}
}

package com.slayerloadout;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Loads the bundled best-in-slot dataset ({@code bis-data.json}) and indexes it
 * by monster name for fast lookup.
 *
 * <p>The data file is the only "database" the plugin needs - it is bundled inside
 * the jar and read with {@link Class#getResourceAsStream(String)} as required by
 * the Plugin Hub (plugins are not unpacked to disk).</p>
 */
@Slf4j
@Singleton
public class BisDataService
{
	private final Map<String, MonsterLoadout> byName = new HashMap<>();
	// One display name per monster (its primary task name) for autocomplete suggestions.
	private final java.util.List<String> primaryNames = new java.util.ArrayList<>();
	private boolean loaded = false;

	// Reuse the client's shared Gson (Plugin Hub forbids creating fresh Gson instances).
	@Inject
	private Gson gson;

	public synchronized void load()
	{
		if (loaded)
		{
			return;
		}
		loaded = true;

		try (InputStream is = BisDataService.class.getResourceAsStream("bis-data.json"))
		{
			if (is == null)
			{
				log.warn("Slayer Loadout: bis-data.json resource was not found");
				return;
			}

			final BisData data = gson.fromJson(
				new InputStreamReader(is, StandardCharsets.UTF_8), BisData.class);

			if (data == null || data.monsters == null)
			{
				log.warn("Slayer Loadout: bis-data.json was empty or malformed");
				return;
			}

			for (MonsterLoadout monster : data.monsters)
			{
				for (String name : monster.getNames())
				{
					byName.put(normalize(name), monster);
				}
				if (!monster.getNames().isEmpty())
				{
					primaryNames.add(monster.getNames().get(0));
				}
			}

			log.debug("Slayer Loadout: loaded loadouts for {} monster aliases", byName.size());
		}
		catch (Exception e)
		{
			log.warn("Slayer Loadout: failed to load bis-data.json", e);
		}
	}

	/**
	 * @param taskName the slayer task / monster name (case-insensitive)
	 * @return the matching loadout, or {@code null} if the task is not in the dataset
	 */
	public MonsterLoadout find(String taskName)
	{
		if (taskName == null)
		{
			return null;
		}

		final String key = normalize(taskName);
		MonsterLoadout exact = byName.get(key);
		if (exact != null)
		{
			return exact;
		}

		// Fall back to a singular/plural tolerant match (e.g. "abyssal demon").
		if (key.endsWith("s"))
		{
			MonsterLoadout singular = byName.get(key.substring(0, key.length() - 1));
			if (singular != null)
			{
				return singular;
			}
		}
		else
		{
			MonsterLoadout plural = byName.get(key + "s");
			if (plural != null)
			{
				return plural;
			}
		}

		return null;
	}

	/**
	 * One name per monster (its primary task name), de-duplicated and sorted, for
	 * autocomplete suggestions. Typing any alias still resolves via {@link #find}.
	 */
	public java.util.List<String> getSuggestionNames()
	{
		return new java.util.ArrayList<>(new java.util.TreeSet<>(primaryNames));
	}

	static String normalize(String s)
	{
		return s == null ? "" : s.toLowerCase(Locale.ENGLISH).trim();
	}
}

package com.slayerloadout;

import java.util.List;

/**
 * Top level container that mirrors the structure of {@code bis-data.json}.
 * Populated by Gson; fields are intentionally package-private.
 */
public class BisData
{
	List<MonsterLoadout> monsters;
}

