	/** Provide the list of known monster names to suggest (called by the plugin). */
	void setSuggestions(List<String> names)
	{
		final List<String> titled = new ArrayList<>(names.size());
		for (String n : names)
		{
			titled.add(titleCase(n));
		}
		Collections.sort(titled);
		this.suggestions = titled;
	}

	private void setupAutocomplete()
	{
		suggestionList.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		suggestionList.setForeground(Color.WHITE);
		suggestionList.setFont(FontManager.getRunescapeSmallFont());
		suggestionList.setSelectionBackground(ColorScheme.BRAND_ORANGE);
		suggestionList.setSelectionForeground(Color.WHITE);
		suggestionList.setFocusable(false);

		final JScrollPane sp = new JScrollPane(suggestionList,
			ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		sp.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));

		suggestionWindow = new JWindow();
		suggestionWindow.setFocusableWindowState(false);
		suggestionWindow.add(sp);

		overrideField.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				refreshSuggestions();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				refreshSuggestions();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				refreshSuggestions();
			}
		});

		suggestionList.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				final String value = suggestionList.getSelectedValue();
				if (value != null)
				{
					acceptSuggestion(value);
				}
			}
		});

		overrideField.addKeyListener(new KeyAdapter()
		{
			@Override
			public void keyPressed(KeyEvent e)
			{
				if (!isSuggestVisible())
				{
					return;
				}
				final int size = suggestionModel.getSize();
				int idx = suggestionList.getSelectedIndex();
				if (e.getKeyCode() == KeyEvent.VK_DOWN)
				{
					idx = Math.min(size - 1, idx + 1);
					suggestionList.setSelectedIndex(idx);
					suggestionList.ensureIndexIsVisible(idx);
					e.consume();
				}
				else if (e.getKeyCode() == KeyEvent.VK_UP)
				{
					idx = Math.max(0, idx - 1);
					suggestionList.setSelectedIndex(idx);
					suggestionList.ensureIndexIsVisible(idx);
					e.consume();
				}
				else if (e.getKeyCode() == KeyEvent.VK_ESCAPE)
				{
					hideSuggestions();
					e.consume();
				}
			}
		});

		overrideField.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent e)
			{
				hideSuggestions();
			}
		});
	}

	/** Apply the highlighted suggestion if any, otherwise whatever was typed. */
	private void applyFromField()
	{
		String chosen = null;
		if (isSuggestVisible() && suggestionList.getSelectedValue() != null)
		{
			chosen = suggestionList.getSelectedValue();
		}
		if (chosen == null)
		{
			final String typed = overrideField.getText().trim();
			if (!typed.isEmpty())
			{
				chosen = typed;
			}
		}
		hideSuggestions();
		if (chosen != null && !chosen.isEmpty())
		{
			listener.onManualTask(chosen);
		}
	}

	private void acceptSuggestion(String name)
	{
		suppressSuggest = true;
		overrideField.setText(name);
		suppressSuggest = false;
		hideSuggestions();
		listener.onManualTask(name);
	}

	private void refreshSuggestions()
	{
		if (suppressSuggest || suggestionWindow == null)
		{
			return;
		}
		final String typed = overrideField.getText().trim().toLowerCase(Locale.ENGLISH);
		if (typed.isEmpty())
		{
			hideSuggestions();
			return;
		}

		suggestionModel.clear();
		int count = 0;
		// Prefix matches first...
		for (String n : suggestions)
		{
			if (n.toLowerCase(Locale.ENGLISH).startsWith(typed))
			{
				suggestionModel.addElement(n);
				if (++count >= 10)
				{
					break;
				}
			}
		}
		// ...then substring matches.
		if (count < 10)
		{
			for (String n : suggestions)
			{
				final String nl = n.toLowerCase(Locale.ENGLISH);
				if (!nl.startsWith(typed) && nl.contains(typed))
				{
					suggestionModel.addElement(n);
					if (++count >= 10)
					{
						break;
					}
				}
			}
		}

		if (suggestionModel.isEmpty())
		{
			hideSuggestions();
			return;
		}
		showSuggestions();
	}

	private void showSuggestions()
	{
		if (!overrideField.isShowing())
		{
			return;
		}
		suggestionList.setVisibleRowCount(Math.min(8, suggestionModel.getSize()));
		suggestionList.clearSelection();
		suggestionWindow.pack();
		final Point p = overrideField.getLocationOnScreen();
		suggestionWindow.setSize(overrideField.getWidth(), suggestionWindow.getPreferredSize().height);
		suggestionWindow.setLocation(p.x, p.y + overrideField.getHeight());
		suggestionWindow.setVisible(true);
	}

	private void hideSuggestions()
	{
		if (suggestionWindow != null)
		{
			suggestionWindow.setVisible(false);
		}
		suggestionList.clearSelection();
	}

	private boolean isSuggestVisible()
	{
		return suggestionWindow != null && suggestionWindow.isVisible();
	}

	private static String titleCase(String s)
	{
		final String[] parts = s.split(" ");
		final StringBuilder sb = new StringBuilder();
		for (int i = 0; i < parts.length; i++)
		{
			if (i > 0)
			{
				sb.append(' ');
			}
			final String p = parts[i];
			if (p.isEmpty())
			{
				continue;
			}
			sb.append(Character.toUpperCase(p.charAt(0))).append(p.substring(1));
		}
		return sb.toString();
	}
}

package com.slayerloadout;

/**
 * Combat/defence stats for a monster, used by the DPS calculator. Populated by
 * Gson from the optional {@code combat} block in {@code bis-data.json}; fields
 * are package-private and may be absent (then the plugin falls back to heuristics).
 */
public class MonsterStats
{
	int hitpoints;
	int defenceLevel;
	int magicLevel;

	// Defensive bonuses by attack type.
	int defStab;
	int defSlash;
	int defCrush;
	int defMagic;
	int defRange;

	/** NPC size in tiles (1 = small). Used for multi-hit weapons like the Scythe. */
	int size = 1;

	int defenceForStyle(AttackStyle style, int meleeType)
	{
		if (style == AttackStyle.RANGED)
		{
			return defRange;
		}
		if (style == AttackStyle.MAGIC)
		{
			return defMagic;
		}
		// meleeType: 0 = stab, 1 = slash, 2 = crush
		if (meleeType == 0)
		{
			return defStab;
		}
		if (meleeType == 2)
		{
			return defCrush;
		}
		return defSlash;
	}
}

package com.slayerloadout;

import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * Best-in-slot recommendations for a single slayer monster.
 *
 * <p>The {@code styles} map is keyed by {@link AttackStyle} name (MELEE / RANGED /
 * MAGIC). Each style maps {@link GearSlot} name to an <b>ordered</b> list of item
 * names, best first. The plugin walks the list and picks the first item the player
 * actually owns, so the lists double as a graceful "downgrade" path.</p>
 *
 * <p>Populated by Gson; fields are package-private by design.</p>
 */
public class MonsterLoadout
{
	/** Names / aliases that appear in the slayer assignment chat message. */
	List<String> names;

	/** "MELEE", "RANGED" or "MAGIC" - the style this plugin highlights first. */
	String recommendedStyle;

	/** Free-form note shown in the panel (mechanics, finishing items, etc.). */
	String notes;

	/** Melee defence weakness ("STAB"/"SLASH"/"CRUSH") used to pick a melee weapon. */
	String meleeWeakness;

	/** Difficulty tier ("Easy"/"Medium"/"Hard"/"Boss"); used for spec-weapon tips. */
	String difficulty;

	/** Recommended spellbook spell for the Magic loadout (e.g. "Ice Barrage (Ancient)"). */
	String mageSpell;

	/** Optional combat/defence stats for the DPS calculator (null = use heuristics). */
	MonsterStats combat;

	/** Combat attributes (e.g. "dragon", "undead", "demon") for bane modifiers. */
	List<String> attributes;

	/**
	 * Protective / mandatory gear for a special mechanic (e.g. Shayzien armour to block
	 * lizardman shaman poison). Surfaced separately from the DPS loadout because it's a
	 * survivability requirement, not a damage choice.
	 */
	List<String> requiredGear;

	/** Explanation shown alongside {@link #requiredGear}. */
	String requiredGearNote;

	/**
	 * True when the task mandates a shield (e.g. an anti-wyvern shield to block icy
	 * breath). A shield occupies the off-hand, so only one-handed weapons may be
	 * recommended - a two-handed weapon would leave no room for the required shield.
	 */
	boolean requiresShield;

	/**
	 * For a "group" task (e.g. Metal Dragons) where the player picks which sub-monster
	 * they're fighting: the list of sub-monster names (each resolvable to its own entry).
	 * When set, the panel shows a picker instead of a single loadout.
	 */
	List<String> subMonsters;

	/** Explanation shown for a group task, above the picker. */
	String groupNote;

	/**
	 * Soft/suggested gear that helps against a special mechanic but is NOT mandatory
	 * (e.g. Insulated boots vs the Rune dragon electricity special). Shown as a
	 * "Warning" section, distinct from {@link #requiredGear}.
	 */
	List<String> warningGear;

	/** Explanation shown alongside {@link #warningGear}. */
	String warningNote;

	/** styleName -> (slotName -> ordered list of item names, best first). */
	Map<String, Map<String, List<String>>> styles;

	List<String> getNames()
	{
		return names == null ? Collections.emptyList() : names;
	}

	String getNotes()
	{
		return notes;
	}

	boolean isBoss()
	{
		return "Boss".equalsIgnoreCase(difficulty);
	}

	/** @return the recommended spellbook spell, or null to let the panel decide. */
	String getMageSpell()
	{
		return (mageSpell == null || mageSpell.trim().isEmpty()) ? null : mageSpell.trim();
	}

	/** @return combat/defence stats for the DPS calc, or null if not seeded. */
	MonsterStats getCombat()
	{
		return combat;
	}

	List<String> getAttributes()
	{
		return attributes == null ? Collections.emptyList() : attributes;
	}

	/** @return mandatory/protective gear item names for this task, or an empty list. */
	List<String> getRequiredGear()
	{
		return requiredGear == null ? Collections.emptyList() : requiredGear;
	}

	/** @return the note shown with the required gear, or null. */
	String getRequiredGearNote()
	{
		return (requiredGearNote == null || requiredGearNote.trim().isEmpty()) ? null : requiredGearNote.trim();
	}

	/** @return true if a shield is mandatory, so only one-handed weapons may be recommended. */
	boolean isRequiresShield()
	{
		return requiresShield;
	}

	/** @return true if this is a group task (player picks a sub-monster from a list). */
	boolean isGroup()
	{
		return subMonsters != null && !subMonsters.isEmpty();
	}

	/** @return the sub-monster names for a group task, or an empty list. */
	List<String> getSubMonsters()
	{
		return subMonsters == null ? Collections.emptyList() : subMonsters;
	}

	/** @return the note shown above a group task's picker, or null. */
	String getGroupNote()
	{
		return (groupNote == null || groupNote.trim().isEmpty()) ? null : groupNote.trim();
	}

	/** @return suggested (non-mandatory) gear shown as a Warning, or an empty list. */
	List<String> getWarningGear()
	{
		return warningGear == null ? Collections.emptyList() : warningGear;
	}

	/** @return the note shown with the warning gear, or null. */
	String getWarningNote()
	{
		return (warningNote == null || warningNote.trim().isEmpty()) ? null : warningNote.trim();
	}

	/** @return "STAB"/"SLASH"/"CRUSH", or null if no weakness is set/recognised. */
	String getMeleeWeakness()
	{
		if (meleeWeakness == null)
		{
			return null;
		}
		final String w = meleeWeakness.trim().toUpperCase(java.util.Locale.ENGLISH);
		return ("STAB".equals(w) || "SLASH".equals(w) || "CRUSH".equals(w)) ? w : null;
	}

	AttackStyle getRecommendedStyle()
	{
		if (recommendedStyle == null)
		{
			return null;
		}
		try
		{
			return AttackStyle.valueOf(recommendedStyle.trim().toUpperCase(java.util.Locale.ENGLISH));
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	/**
	 * @return the ordered item-name lists per slot for the given style, or an
	 * empty map if the style is not viable / not defined for this monster.
	 */
	Map<String, List<String>> getStyle(AttackStyle style)
	{
		if (styles == null || style == null)
		{
			return Collections.emptyMap();
		}
		Map<String, List<String>> m = styles.get(style.name());
		return m == null ? Collections.emptyMap() : m;
	}

	boolean hasStyle(AttackStyle style)
	{
		return !getStyle(style).isEmpty();
	}
}

package com.slayerloadout;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@Slf4j
@PluginDescriptor(
	name = "Slayer Loadout",
	description = "Shows the best gear you own (Melee, Ranged, Magic) for your current slayer task",
	tags = {"slayer", "gear", "bis", "loadout", "combat", "bank", "task"}
)
public class SlayerLoadoutPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private SlayerLoadoutConfig config;

	@Inject
	private BisDataService bisData;

	private final SlayerTaskTracker tracker = new SlayerTaskTracker();

	private SlayerLoadoutPanel panel;
	private NavigationButton navButton;

	// Snapshot of owned items, rebuilt on the client thread and read on the EDT.
	private volatile OwnedItemIndex owned = new OwnedItemIndex();

	// Set when a watched item container changes; debounced to one rebuild per game tick.
	private volatile boolean ownedDirty;

	// Transient in-panel override: a monster the user typed to preview. Takes
	// precedence over the auto-detected task until they hit "Back to my task".
	private volatile String panelOverride;

	// Player's (boosted) combat levels for the DPS calculator.
	private volatile PlayerStats playerStats = PlayerStats.maxed();

	@Override
	protected void startUp()
	{
		bisData.load();

		// Restore the last detected task so the panel is useful immediately.
		tracker.setCurrentTask(config.lastTask());

		panel = new SlayerLoadoutPanel(new SlayerLoadoutPanel.TaskOverrideListener()
		{
			@Override
			public void onManualTask(String monster)
			{
				panelOverride = monster;
				rebuild();
			}

			@Override
			public void onClearOverride()
			{
				panelOverride = null;
				rebuild();
			}

			@Override
			public MonsterLoadout resolveMonster(String name)
			{
				return bisData.find(name);
			}
		});

		navButton = NavigationButton.builder()
			.tooltip("Slayer Loadout")
			.icon(createIcon())
			.priority(7)
			.panel(panel)
			.build();

		panel.setSuggestions(bisData.getSuggestionNames());

		clientToolbar.addNavigation(navButton);

		clientThread.invokeLater(() ->
		{
			refreshStats();
			refreshOwned();
			rebuild();
		});
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		panel = null;
		navButton = null;
		owned = new OwnedItemIndex();
	}

	@Provides
	SlayerLoadoutConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SlayerLoadoutConfig.class);
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		final ChatMessageType type = event.getType();
		if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM)
		{
			return;
		}

		if (tracker.parse(event.getMessage()))
		{
			final String task = tracker.getCurrentTask();
			configManager.setConfiguration(SlayerLoadoutConfig.GROUP, "lastTask", task == null ? "" : task);
			rebuild();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		// Only recompute when the BANK changes - i.e. while the bank is open, when we
		// have full visibility of everything the player owns. We deliberately ignore
		// INVENTORY and EQUIPMENT changes so that swapping gear during normal play does
		// NOT recalculate the recommendation; it stays the "best you own" set captured
		// at the bank. Debounced to one rebuild per game tick to coalesce rapid deposits.
		if (event.getContainerId() == InventoryID.BANK.getId())
		{
			ownedDirty = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (ownedDirty)
		{
			ownedDirty = false;
			refreshOwned();
			rebuild();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			refreshStats();
			refreshOwned();
			rebuild();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		refreshStats();
		rebuild();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!SlayerLoadoutConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		clientThread.invokeLater(() ->
		{
			refreshStats();
			refreshOwned();
			rebuild();
		});
	}

	/**
	 * Rebuild the {@link #owned} snapshot from the bank, inventory and worn
	 * equipment containers. Must run on the client thread.
	 */
	private void refreshOwned()
	{
		final OwnedItemIndex index = new OwnedItemIndex();

		if (config.includeBank())
		{
			addContainer(index, InventoryID.BANK);
		}
		if (config.includeInventory())
		{
			addContainer(index, InventoryID.INVENTORY);
		}
		if (config.includeEquipment())
		{
			addContainer(index, InventoryID.EQUIPMENT);
		}

		// Flag gear the player currently has on them (worn or in inventory) so the panel
		// can highlight "ready to use" items. Done independently of the include toggles
		// above so the highlight is accurate even if a container is excluded from scanning.
		markReady(index, InventoryID.EQUIPMENT);
		markReady(index, InventoryID.INVENTORY);

		owned = index;
	}

	/** Mark every (canonicalised) item in a container as ready to use - worn or carried. */
	private void markReady(OwnedItemIndex index, InventoryID inventoryID)
	{
		final ItemContainer container = client.getItemContainer(inventoryID);
		if (container == null)
		{
			return;
		}
		for (Item item : container.getItems())
		{
			if (item == null)
			{
				continue;
			}
			final int rawId = item.getId();
			if (rawId <= 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			index.markReady(itemManager.canonicalize(rawId));
		}
	}

	/** Read the player's boosted combat levels for the DPS calculator. Client thread. */
	private void refreshStats()
	{
		playerStats = new PlayerStats(
			client.getBoostedSkillLevel(Skill.ATTACK),
			client.getBoostedSkillLevel(Skill.STRENGTH),
			client.getBoostedSkillLevel(Skill.DEFENCE),
			client.getBoostedSkillLevel(Skill.RANGED),
			client.getBoostedSkillLevel(Skill.MAGIC),
			client.getBoostedSkillLevel(Skill.HITPOINTS));
	}

	/**
	 * Teleport / novelty items that occupy a gear slot but provide no real combat use, so
	 * they should never be recommended. (Items like the Ring of shadows DO carry offensive
	 * bonuses, so they stay eligible and are intentionally NOT listed here.)
	 */
	private static final java.util.Set<String> EXCLUDED_GEAR = new java.util.HashSet<>(java.util.Arrays.asList(
		"skull sceptre"));

	private static boolean isExcludedGear(String name)
	{
		if (name == null)
		{
			return false;
		}
		final String n = name.toLowerCase(java.util.Locale.ENGLISH);
		for (String frag : EXCLUDED_GEAR)
		{
			if (n.contains(frag))
			{
				return true;
			}
		}
		return false;
	}

	private void addContainer(OwnedItemIndex index, InventoryID inventoryID)
	{
		final ItemContainer container = client.getItemContainer(inventoryID);
		if (container == null)
		{
			return;
		}

		for (Item item : container.getItems())
		{
			if (item == null)
			{
				continue;
			}
			final int rawId = item.getId();
			if (rawId <= 0 || item.getQuantity() <= 0)
			{
				// Skip empty slots and bank placeholders (quantity 0).
				continue;
			}

			// Resolve noted items and placeholders back to the real item.
			final int canonical = itemManager.canonicalize(rawId);
			final String name = itemManager.getItemComposition(canonical).getName();

			// Teleport / novelty items (e.g. the skull sceptre) wear an equipment slot but
			// are not real combat gear - never recommend them.
			if (isExcludedGear(name))
			{
				continue;
			}

			final ItemStats stats = itemManager.getItemStats(canonical);
			GearSlot slot = null;
			if (stats != null && stats.isEquipable() && stats.getEquipment() != null)
			{
				final ItemEquipmentStats e = stats.getEquipment();
				slot = GearSlot.fromEquipmentSlot(e.getSlot());
				if (slot != null)
				{
					final int meleeAtk = Math.max(e.getAstab(), Math.max(e.getAslash(), e.getAcrush()));
					final int totalDef = e.getDstab() + e.getDslash() + e.getDcrush() + e.getDmagic() + e.getDrange();
					final int magicDmg = (int) e.getMdmg();

					final int meleeScore = e.getStr() * 10 + meleeAtk + totalDef / 10;
					final int rangedScore = e.getRstr() * 10 + e.getArange() + totalDef / 10;
					final int magicScore = magicDmg * 10 + e.getAmagic() + totalDef / 10;

					// For weapons, classify the intended style by the dominant attack bonus,
					// so a melee weapon never gets suggested for a Ranged/Magic loadout.
					AttackStyle weaponStyle = null;
					if (slot == GearSlot.WEAPON)
					{
						final int rangeAtk = e.getArange();
						final int magicAtk = e.getAmagic();
						if (magicAtk > meleeAtk && magicAtk >= rangeAtk)
						{
							weaponStyle = AttackStyle.MAGIC;
						}
						else if (rangeAtk > meleeAtk && rangeAtk >= magicAtk)
						{
							weaponStyle = AttackStyle.RANGED;
						}
						else
						{
							weaponStyle = AttackStyle.MELEE;
						}
					}

					index.addEquippable(name, canonical, slot, meleeScore, rangedScore, magicScore, e.isTwoHanded(),
						weaponStyle, e.getStr(), e.getAstab(), e.getAslash(), e.getAcrush(), e);
				}
			}

			if (slot == null)
			{
				index.add(name, canonical);
			}
		}
	}

	private boolean hasPanelOverride()
	{
		return panelOverride != null && !panelOverride.trim().isEmpty();
	}

	private String resolveTaskName()
	{
		// 1) in-panel "preview" override, 2) persistent config override, 3) detected task.
		if (hasPanelOverride())
		{
			return panelOverride.trim();
		}
		final String manual = config.manualTask();
		if (manual != null && !manual.trim().isEmpty())
		{
			return manual.trim();
		}
		return tracker.getCurrentTask();
	}

	private void rebuild()
	{
		final String task = resolveTaskName();
		final boolean override = hasPanelOverride();
		final boolean preferBroadBolts = config.preferBroadBolts();
		final boolean assumePrayers = config.assumePrayers();
		final boolean preferBlowpipe = config.preferBlowpipe();
		final PlayerStats stats = playerStats;
		final MonsterLoadout loadout = task == null ? null : bisData.find(task);
		final OwnedItemIndex snapshot = owned;

		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.update(task, override, preferBroadBolts, assumePrayers, preferBlowpipe, stats, loadout,
					snapshot, itemManager);
			}
		});
	}

	/** Build a small navigation-button icon at runtime (no binary resource needed). */
	private static BufferedImage createIcon()
	{
		final int size = 24;
		final BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(0xE0, 0x90, 0x20));
		g.fillRoundRect(1, 1, size - 2, size - 2, 6, 6);
		g.setColor(new Color(0x2B, 0x2B, 0x2B));
		g.setFont(g.getFont().deriveFont(java.awt.Font.BOLD, 14f));
		final String text = "S";
		final int tw = g.getFontMetrics().stringWidth(text);
		g.drawString(text, (size - tw) / 2, 17);
		g.dispose();
		return image;
	}
}

package com.slayerloadout;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import net.runelite.client.game.ItemEquipmentStats;

/**
 * A snapshot of the items the player currently owns (bank + inventory + worn
 * equipment), indexed both by name (for curated best-in-slot matching) and by
 * equipment slot (so we can fall back to the player's best owned item for a slot
 * when they own none of the curated picks).
 */
public class OwnedItemIndex
{
	/** A single owned, equippable item with pre-computed per-style scores. */
	public static final class OwnedItem
	{
		public final int id;
		public final String name;
		public final GearSlot slot;       // may be null for non-equippable items
		public final int meleeScore;
		public final int rangedScore;
		public final int magicScore;
		public final boolean twoHanded;
		// For weapons only: the combat style this weapon is actually meant for
		// (by its dominant attack bonus). null for non-weapon items.
		public final AttackStyle weaponStyle;
		// Raw stats kept for weakness-aware melee weapon scoring.
		public final int strength;
		public final int aStab;
		public final int aSlash;
		public final int aCrush;
		// Full equipment stats for the DPS calculator (null for non-equippable items).
		public final ItemEquipmentStats equip;

		OwnedItem(int id, String name, GearSlot slot, int meleeScore, int rangedScore, int magicScore,
			boolean twoHanded, AttackStyle weaponStyle, int strength, int aStab, int aSlash, int aCrush,
			ItemEquipmentStats equip)
		{
			this.id = id;
			this.name = name;
			this.slot = slot;
			this.meleeScore = meleeScore;
			this.rangedScore = rangedScore;
			this.magicScore = magicScore;
			this.twoHanded = twoHanded;
			this.weaponStyle = weaponStyle;
			this.strength = strength;
			this.aStab = aStab;
			this.aSlash = aSlash;
			this.aCrush = aCrush;
			this.equip = equip;
		}

		int score(AttackStyle style)
		{
			if (style == AttackStyle.MELEE)
			{
				return meleeScore;
			}
			if (style == AttackStyle.RANGED)
			{
				return rangedScore;
			}
			return magicScore;
		}

		/** Strength-weighted attack score against a specific melee defence type. */
		int meleeWeaknessScore(String weakness)
		{
			final int atk = "STAB".equals(weakness) ? aStab
				: "CRUSH".equals(weakness) ? aCrush
				: aSlash;
			return strength * 10 + atk;
		}
	}

	private final Map<String, OwnedItem> byName = new HashMap<>();
	private final Map<GearSlot, List<OwnedItem>> bySlot = new EnumMap<>(GearSlot.class);
	/**
	 * Canonical item ids the player currently has worn or in their inventory ("ready to
	 * use" right now, as opposed to sitting in the bank). Used to highlight such items in
	 * the panel.
	 */
	private final Set<Integer> readyIds = new HashSet<>();

	/** Mark a canonical item id as worn or carried (ready to use without a bank trip). */
	public void markReady(int id)
	{
		readyIds.add(id);
	}

	/** @return true if the given canonical item id is currently worn or in the inventory. */
	public boolean isReady(int id)
	{
		return readyIds.contains(id);
	}

	/** Record a non-equippable (or unclassified) owned item - name lookup only. */
	public void add(String name, int id)
	{
		if (name == null || name.isEmpty())
		{
			return;
		}
		byName.putIfAbsent(normalize(name), new OwnedItem(id, name, null, 0, 0, 0, false, null, 0, 0, 0, 0, null));
	}

	/** Record an owned equippable item with its slot and per-style scores. */
	public void addEquippable(String name, int id, GearSlot slot,
		int meleeScore, int rangedScore, int magicScore, boolean twoHanded, AttackStyle weaponStyle,
		int strength, int aStab, int aSlash, int aCrush, ItemEquipmentStats equip)
	{
		if (name == null || name.isEmpty())
		{
			return;
		}
		final OwnedItem item = new OwnedItem(id, name, slot, meleeScore, rangedScore, magicScore, twoHanded,
			weaponStyle, strength, aStab, aSlash, aCrush, equip);
		byName.putIfAbsent(normalize(name), item);
		if (slot != null)
		{
			bySlot.computeIfAbsent(slot, k -> new ArrayList<>()).add(item);
		}
	}

	/**
	 * Find an owned item matching a best-in-slot name (exact, then prefix so
	 * charged/degradable variants like "Dharok's helm 100" still match).
	 */
	public OwnedItem match(String bisName)
	{
		final String key = normalize(bisName);
		if (key.isEmpty())
		{
			return null;
		}

		final OwnedItem exact = byName.get(key);
		if (exact != null)
		{
			return exact;
		}

		for (Map.Entry<String, OwnedItem> entry : byName.entrySet())
		{
			final String owned = entry.getKey();
			if (owned.startsWith(key + " ") || owned.startsWith(key + "("))
			{
				return entry.getValue();
			}
		}

		// Slayer helmet colour/boss variants (Black, Red, Hydra, Twisted, Tztok, ...)
		// all END with the base name, so a suffix match catches them. The "(i)" curated
		// entry is listed first, so imbued variants are preferred over un-imbued.
		if (key.equals("slayer helmet (i)") || key.equals("slayer helmet"))
		{
			for (Map.Entry<String, OwnedItem> entry : byName.entrySet())
			{
				if (entry.getKey().endsWith(key))
				{
					return entry.getValue();
				}
			}
		}
		return null;
	}

	/**
	 * The best owned item for a slot, scored for the given attack style.
	 *
	 * <p>For the weapon slot, only weapons actually built for that style are
	 * considered (so a melee spear can't be suggested for a Magic loadout).
	 * Items with no useful stats (cosmetics) are skipped.</p>
	 */
	public OwnedItem bestInSlot(GearSlot slot, AttackStyle style)
	{
		return bestInSlot(slot, style, false);
	}

	/**
	 * As {@link #bestInSlot(GearSlot, AttackStyle)}, but when {@code oneHandedWeaponOnly}
	 * is set, two-handed weapons are skipped for the weapon slot (used when the task
	 * mandates a shield, which can't be worn alongside a two-handed weapon).
	 */
	public OwnedItem bestInSlot(GearSlot slot, AttackStyle style, boolean oneHandedWeaponOnly)
	{
		final List<OwnedItem> list = bySlot.get(slot);
		if (list == null || list.isEmpty())
		{
			return null;
		}

		OwnedItem best = null;
		int bestScore = 0; // strictly-positive required, which excludes 0-stat cosmetics
		for (OwnedItem item : list)
		{
			if (slot == GearSlot.WEAPON && item.weaponStyle != style)
			{
				continue;
			}
			if (oneHandedWeaponOnly && slot == GearSlot.WEAPON && item.twoHanded)
			{
				continue;
			}
			// A Void helm only helps its own style (it unlocks that style's Void set
			// bonus and gives nothing useful otherwise), so never let the melee helm
			// fill a Ranged/Magic head slot, and vice-versa.
			if (slot == GearSlot.HEAD && isMismatchedVoidHelm(item.name, style))
			{
				continue;
			}
			final int s = item.score(style);
			if (s > bestScore)
			{
				bestScore = s;
				best = item;
			}
		}
		return best;
	}

	/**
	 * True if {@code name} is a Void Knight helm built for a combat style other than
	 * {@code style}. The Void melee/ranger/mage helms are style-locked, so each must
	 * only ever appear in its own style's loadout.
	 */
	private static boolean isMismatchedVoidHelm(String name, AttackStyle style)
	{
		final String n = name.toLowerCase(Locale.ENGLISH);
		if (!n.contains("void"))
		{
			return false;
		}
		if (n.contains("melee"))
		{
			return style != AttackStyle.MELEE;
		}
		if (n.contains("ranger"))
		{
			return style != AttackStyle.RANGED;
		}
		if (n.contains("mage"))
		{
			return style != AttackStyle.MAGIC;
		}
		return false;
	}

	/** All owned items in a slot (used for weapon-aware ammo selection). */
	public List<OwnedItem> itemsInSlot(GearSlot slot)
	{
		return bySlot.getOrDefault(slot, Collections.emptyList());
	}

	/** All owned weapons whose intended combat style matches the given style. */
	public List<OwnedItem> weaponsForStyle(AttackStyle style)
	{
		final List<OwnedItem> all = bySlot.getOrDefault(GearSlot.WEAPON, Collections.emptyList());
		final List<OwnedItem> out = new ArrayList<>();
		for (OwnedItem w : all)
		{
			if (w.weaponStyle == style)
			{
				out.add(w);
			}
		}
		return out;
	}

	/**
	 * The best owned melee weapon against a given defence weakness
	 * ("STAB"/"SLASH"/"CRUSH"), scored by strength + that attack type.
	 */
	public OwnedItem bestMeleeWeaponForWeakness(String weakness)
	{
		return bestMeleeWeaponForWeakness(weakness, false);
	}

	/**
	 * As {@link #bestMeleeWeaponForWeakness(String)}, but skips two-handed weapons when
	 * {@code oneHandedOnly} is set (used when the task mandates a shield).
	 */
	public OwnedItem bestMeleeWeaponForWeakness(String weakness, boolean oneHandedOnly)
	{
		final List<OwnedItem> list = bySlot.get(GearSlot.WEAPON);
		if (list == null)
		{
			return null;
		}
		OwnedItem best = null;
		int bestScore = 0;
		for (OwnedItem item : list)
		{
			if (item.weaponStyle != AttackStyle.MELEE)
			{
				continue;
			}
			if (oneHandedOnly && item.twoHanded)
			{
				continue;
			}
			final int s = item.meleeWeaknessScore(weakness);
			if (s > bestScore)
			{
				bestScore = s;
				best = item;
			}
		}
		return best;
	}

	public int size()
	{
		return byName.size();
	}

	static String normalize(String s)
	{
		return s == null ? "" : s.toLowerCase(Locale.ENGLISH).trim();
	}
}

package com.slayerloadout;

/**
 * The three combat styles the plugin builds a loadout for.
 */
public enum AttackStyle
{
	MELEE("Melee"),
	RANGED("Ranged"),
	MAGIC("Magic");

	private final String displayName;

	AttackStyle(String displayName)
	{
		this.displayName = displayName;
	}

	public String getDisplayName()
	{
		return displayName;
	}
}

package com.slayerloadout;

import java.util.List;
import java.util.Locale;
import java.util.Map;
import net.runelite.client.game.ItemEquipmentStats;

/**
 * A first-cut OSRS DPS calculator. Implements the standard max-hit / accuracy /
 * DPS formulas for melee, ranged and (approximate) magic, plus the major
 * on-task and weapon modifiers (Slayer helmet, Salve, Dragon hunter, demonbane,
 * Twisted bow, Tumeken's shadow, Scythe, Void).
 *
 * <p>Assumptions for v1: aggressive melee / rapid ranged stances, the standard
 * offensive prayer per style when {@code prayers} is true, and magic damage from
 * a powered staff (level-based) or a generic Fire Surge base for cast spells.
 * Values are estimates intended for comparing loadouts, not exact simulation.</p>
 */
public final class DpsCalculator
{
	private DpsCalculator()
	{
	}

	/** Compute estimated DPS for a fully-specified loadout against a monster. */
	public static double computeDps(AttackStyle style, PlayerStats p, boolean prayers,
		Map<GearSlot, OwnedItemIndex.OwnedItem> loadout, MonsterStats m, List<String> attributes)
	{
		if (p == null || m == null)
		{
			return 0;
		}
		final OwnedItemIndex.OwnedItem weapon = loadout.get(GearSlot.WEAPON);
		if (weapon == null || weapon.equip == null)
		{
			return 0;
		}

		int aStab = 0, aSlash = 0, aCrush = 0, aMagic = 0, aRange = 0;
		int meleeStr = 0, rangedStr = 0, magicDmg = 0;
		for (OwnedItemIndex.OwnedItem it : loadout.values())
		{
			if (it == null || it.equip == null)
			{
				continue;
			}
			final ItemEquipmentStats e = it.equip;
			aStab += e.getAstab();
			aSlash += e.getAslash();
			aCrush += e.getAcrush();
			aMagic += e.getAmagic();
			aRange += e.getArange();
			meleeStr += e.getStr();
			rangedStr += e.getRstr();
			magicDmg += (int) e.getMdmg();
		}

		final String wname = weapon.name.toLowerCase(Locale.ENGLISH);
		final boolean undead = attributes != null && attributes.contains("undead");
		final boolean dragon = attributes != null && attributes.contains("dragon");
		final boolean demon = attributes != null && attributes.contains("demon");
		final VoidKind vk = voidKind(loadout, style);
		final boolean voidSet = vk != VoidKind.NONE;

		final double[] gm = generalMultiplier(loadout, undead, style);
		double accMult = gm[0];
		double dmgMult = gm[1];

		int speed = weapon.equip.getAspeed();
		if (speed <= 0)
		{
			speed = 4;
		}

		if (style == AttackStyle.MELEE)
		{
			if (dragon && wname.contains("dragon hunter lance"))
			{
				accMult *= 1.20;
				dmgMult *= 1.20;
			}
			if (demon && (wname.contains("arclight") || wname.contains("emberlight") || wname.contains("darklight")))
			{
				accMult *= 1.70;
				dmgMult *= 1.70;
			}
			double best = 0;
			for (int type = 0; type < 3; type++)
			{
				final int atkBonus = type == 0 ? aStab : type == 2 ? aCrush : aSlash;
				final int defBonus = m.defenceForStyle(AttackStyle.MELEE, type);
				final double d = meleeDps(p, prayers, atkBonus, meleeStr, speed, m.defenceLevel, defBonus, accMult, dmgMult, voidSet);
				if (d > best)
				{
					best = d;
				}
			}
			if (wname.contains("scythe of vitur") && m.size >= 2)
			{
				best *= 1.75; // approximate value of the second and third hits
			}
			return best;
		}

		if (style == AttackStyle.RANGED)
		{
			if (dragon && wname.contains("dragon hunter crossbow"))
			{
				accMult *= 1.30;
				dmgMult *= 1.25;
			}
			if (wname.contains("twisted bow"))
			{
				final int mag = Math.max(0, Math.min(m.magicLevel, 350));
				final double accBoost = (140.0 + (3.0 * mag - 10) / 100.0
					- Math.pow((3.0 * mag / 10.0 - 100), 2) / 100.0) / 100.0;
				final double dmgBoost = (250.0 + (3.0 * mag - 14) / 100.0
					- Math.pow((3.0 * mag / 10.0 - 140), 2) / 100.0) / 100.0;
				accMult *= clamp(accBoost, 0.0, 1.40);
				dmgMult *= clamp(dmgBoost, 0.0, 2.50);
			}
			if (vk == VoidKind.ELITE)
			{
				dmgMult *= 1.025; // Elite Void ranged: +2.5% damage on top of the base +10% set.
			}
			final int rapidSpeed = Math.max(1, speed - 1);
			return rangedDps(p, prayers, aRange, rangedStr, rapidSpeed, m.defenceLevel, m.defRange, accMult, dmgMult, voidSet);
		}

		// MAGIC
		boolean shadow = wname.contains("shadow");
		if (shadow)
		{
			magicDmg *= 3;
			aMagic *= 3;
		}
		if (vk != VoidKind.NONE)
		{
			accMult *= 1.45; // Void mage set: +45% magic accuracy.
			if (vk == VoidKind.ELITE)
			{
				magicDmg += 5; // Elite Void: +5% magic damage.
			}
		}
		final int baseMax = magicBaseMax(wname, p.magic);
		final int magicSpeed = isPoweredStaffName(wname) ? speed : 5;
		return magicDps(p, prayers, aMagic, magicDmg, baseMax, magicSpeed, m.magicLevel, m.defMagic, accMult, dmgMult);
	}

	private static double meleeDps(PlayerStats p, boolean prayers, int atkBonus, int strBonus, int speed,
		int monDefLevel, int monDefBonus, double accMult, double dmgMult, boolean voidSet)
	{
		final double strPray = prayers ? 1.23 : 1.0;
		final double attPray = prayers ? 1.20 : 1.0;
		int effStr = (int) Math.floor(p.strength * strPray) + 3 + 8;
		int effAtt = (int) Math.floor(p.attack * attPray) + 8;
		if (voidSet)
		{
			effStr = (int) Math.floor(effStr * 1.10);
			effAtt = (int) Math.floor(effAtt * 1.10);
		}
		int maxHit = (int) Math.floor(0.5 + effStr * (strBonus + 64) / 640.0);
		maxHit = (int) Math.floor(maxHit * dmgMult);
		final double attRoll = effAtt * (atkBonus + 64) * accMult;
		final double defRoll = (monDefLevel + 9) * (monDefBonus + 64);
		final double hc = hitChance(attRoll, defRoll);
		return (hc * maxHit / 2.0) / (speed * 0.6);
	}

	private static double rangedDps(PlayerStats p, boolean prayers, int atkBonus, int strBonus, int speed,
		int monDefLevel, int monDefBonus, double accMult, double dmgMult, boolean voidSet)
	{
		final double pray = prayers ? 1.23 : 1.0;
		final double attPray = prayers ? 1.20 : 1.0;
		int effStr = (int) Math.floor(p.ranged * pray) + 8;
		int effAtt = (int) Math.floor(p.ranged * attPray) + 8;
		if (voidSet)
		{
			effStr = (int) Math.floor(effStr * 1.10);
			effAtt = (int) Math.floor(effAtt * 1.10);
		}
		int maxHit = (int) Math.floor(0.5 + effStr * (strBonus + 64) / 640.0);
		maxHit = (int) Math.floor(maxHit * dmgMult);
		final double attRoll = effAtt * (atkBonus + 64) * accMult;
		final double defRoll = (monDefLevel + 9) * (monDefBonus + 64);
		final double hc = hitChance(attRoll, defRoll);
		return (hc * maxHit / 2.0) / (speed * 0.6);
	}

	private static double magicDps(PlayerStats p, boolean prayers, int magicAttBonus, int magicDmgBonus,
		int baseMax, int speed, int monMagicLevel, int monMagicDef, double accMult, double dmgMult)
	{
		int maxHit = (int) Math.floor(baseMax * (1.0 + magicDmgBonus / 100.0));
		maxHit = (int) Math.floor(maxHit * dmgMult);
		final double magPray = prayers ? 1.25 : 1.0;
		final int effMagic = (int) Math.floor(p.magic * magPray) + 9;
		final double attRoll = effMagic * (magicAttBonus + 64) * accMult;
		final double defRoll = (monMagicLevel + 9) * (monMagicDef + 64);
		final double hc = hitChance(attRoll, defRoll);
		return (hc * maxHit / 2.0) / (speed * 0.6);
	}

	private static double hitChance(double attRoll, double defRoll)
	{
		if (attRoll > defRoll)
		{
			return 1.0 - (defRoll + 2.0) / (2.0 * (attRoll + 1.0));
		}
		return attRoll / (2.0 * (defRoll + 1.0));
	}

	private static double[] generalMultiplier(Map<GearSlot, OwnedItemIndex.OwnedItem> loadout, boolean undead,
		AttackStyle style)
	{
		final OwnedItemIndex.OwnedItem neck = loadout.get(GearSlot.NECK);
		final OwnedItemIndex.OwnedItem head = loadout.get(GearSlot.HEAD);
		final String neckName = neck == null ? "" : neck.name.toLowerCase(Locale.ENGLISH);

		// Salve amulet vs undead. It does NOT stack with the slayer helm / black mask:
		// when both are worn only the salve bonus applies, so salve takes precedence here.
		if (undead && neckName.contains("salve amulet"))
		{
			final double m = 1.0 + salveBonus(neckName, style);
			return new double[]{m, m};
		}

		final boolean slayerHelm = head != null
			&& (head.name.toLowerCase(Locale.ENGLISH).contains("slayer helmet")
			|| head.name.toLowerCase(Locale.ENGLISH).contains("black mask"));
		if (slayerHelm)
		{
			final double m = 1.0 + 1.0 / 6.0;
			return new double[]{m, m};
		}
		return new double[]{1.0, 1.0};
	}

	/**
	 * Salve amulet accuracy/damage bonus vs undead, by variant and style. Base/(e)
	 * help melee only (16.67% / 20%); (i)/(ei) also cover ranged and magic — (i) gives
	 * 16.67% melee &amp; ranged and 15% magic, (ei) gives 20% to all three styles.
	 */
	private static double salveBonus(String neckName, AttackStyle style)
	{
		final boolean ei = neckName.contains("(ei)");
		final boolean imbued = ei || neckName.contains("(i)");
		final boolean enchanted = ei || neckName.contains("(e)");
		final double high = 0.20;
		final double low = 1.0 / 6.0; // 16.67%
		if (style == AttackStyle.MELEE)
		{
			return enchanted ? high : low;
		}
		// Ranged and Magic only benefit from an imbued salve.
		if (!imbued)
		{
			return 0.0;
		}
		if (style == AttackStyle.MAGIC)
		{
			return ei ? high : 0.15;
		}
		return ei ? high : low; // RANGED
	}

	private static int magicBaseMax(String wname, int magicLevel)
	{
		final int third = magicLevel / 3;
		if (wname.contains("shadow"))
		{
			return third + 1;
		}
		if (wname.contains("sanguinesti"))
		{
			return third - 1;
		}
		if (wname.contains("trident of the swamp"))
		{
			return third - 2;
		}
		if (wname.contains("trident of the seas"))
		{
			return third - 5;
		}
		if (wname.contains("accursed sceptre"))
		{
			return third - 3;
		}
		if (wname.contains("eye of ayak"))
		{
			return third - 6; // OSRS Wiki: base max hit = floor(Magic/3) - 6.
		}
		// Cast spell (non-powered weapon): assume a high-tier surge.
		return 24;
	}

	private static boolean isPoweredStaffName(String wname)
	{
		return wname.contains("trident") || wname.contains("sanguinesti")
			|| wname.contains("shadow") || wname.contains("accursed sceptre")
			|| wname.contains("eye of ayak");
	}

	private enum VoidKind
	{
		NONE, REGULAR, ELITE
	}

	/**
	 * Detect a complete, style-correct Void Knight set in the loadout. The worn helm
	 * must match {@code style} (melee/ranger/mage), and the gloves plus a top and robe
	 * (regular or elite) are all required. ELITE is only returned when BOTH the top
	 * and robe are the elite versions, matching the in-game set effect.
	 */
	private static VoidKind voidKind(Map<GearSlot, OwnedItemIndex.OwnedItem> loadout, AttackStyle style)
	{
		final OwnedItemIndex.OwnedItem head = loadout.get(GearSlot.HEAD);
		final OwnedItemIndex.OwnedItem body = loadout.get(GearSlot.BODY);
		final OwnedItemIndex.OwnedItem legs = loadout.get(GearSlot.LEGS);
		final OwnedItemIndex.OwnedItem hands = loadout.get(GearSlot.HANDS);
		if (head == null || body == null || legs == null || hands == null)
		{
			return VoidKind.NONE;
		}
		final String h = head.name.toLowerCase(Locale.ENGLISH);
		final String b = body.name.toLowerCase(Locale.ENGLISH);
		final String l = legs.name.toLowerCase(Locale.ENGLISH);
		final String g = hands.name.toLowerCase(Locale.ENGLISH);
		if (!h.contains("void") || !b.contains("void") || !l.contains("void") || !g.contains("void"))
		{
			return VoidKind.NONE;
		}
		final boolean helmMatches =
			(style == AttackStyle.MELEE && h.contains("melee"))
			|| (style == AttackStyle.RANGED && h.contains("ranger"))
			|| (style == AttackStyle.MAGIC && h.contains("mage"));
		if (!helmMatches)
		{
			return VoidKind.NONE;
		}
		return (b.contains("elite") && l.contains("elite")) ? VoidKind.ELITE : VoidKind.REGULAR;
	}

	private static double clamp(double v, double lo, double hi)
	{
		return Math.max(lo, Math.min(hi, v));
	}
}
